// ─── Datos del mensaje de Telegram ───────────────────────────
const msg       = $json.message?.text || '';
const chatId    = $json.message?.chat?.id;
const firstName = $json.message?.from?.first_name || '';
const lastName  = $json.message?.from?.last_name  || '';
const tgName    = [firstName, lastName].filter(Boolean).join(' ') || 'Cliente Telegram';

// ─── ¿Es un mensaje de pedido? ────────────────────────────────
const esPedido = /\bpedido\b|\bpido\b|\bquiero\b|\bquisiera\b|\border\b|\bsolicito\b|\bme trae\b/i.test(msg);

if (!esPedido) {
  return { valid: false, chatId, msg };
}

// ─── Extractor de campos con regex ────────────────────────────
function extract(text, ...patterns) {
  for (const re of patterns) {
    const m = text.match(re);
    if (m) return m[1].trim();
  }
  return '';
}

const cliente = extract(msg,
  /(?:nombre|llamo|soy|me llamo)[:\s]+([^\n,;]+)/i
) || tgName;

const telefono = extract(msg,
  /(?:tel[eé]f?(?:ono)?|cel(?:ular)?|whatsapp|n[uú]mero|phone|m[oó]vil)[:\s]+([+\d\s\-().]{7,})/i
);

const direccion = extract(msg,
  /(?:direcci[oó]n|domicilio|calle|av(?:enida)?\.?|entregar? en|enviar? a|domicilio)[:\s]+([^\n]+)/i
);

const notas = extract(msg,
  /(?:notas?|observaciones?|instrucciones?|comentarios?|sin \w|con extra)[:\s]+([^\n]+)/i
);

// ─── Parsear items: "2 hamburguesas", "1x pizza" ──────────────
const items = [];
const itemRe = /(\d+)\s*[xX×]?\s*([a-záéíóúüñA-ZÁÉÍÓÚÜÑ][\w\s]+?)(?=\s*(?:,|\n|\by\b|\+|$))/g;
let m;
while ((m = itemRe.exec(msg)) !== null) {
  const nombre = m[2].trim().replace(/\s+/g, ' ');
  if (nombre.length > 1) items.push({ nombre, cantidad: parseInt(m[1]), precio: 0 });
}

// Fallback si no se encontraron items estructurados
if (items.length === 0) {
  const primera = msg
    .replace(/quiero|pido|quisiera|pedido|orden/gi, '')
    .trim()
    .split('\n')[0]
    .substring(0, 120);
  items.push({ nombre: primera || 'Pedido especial', cantidad: 1, precio: 0 });
}

// ─── Body JSON listo para POST /api/pedido ────────────────────
const body = JSON.stringify({ cliente, telefono, direccion, notas, items });

return { valid: true, chatId, cliente, telefono, direccion, notas, items, body };

